// 機器情報の更新(PC・サーバ共通)。仮の値を正式な値に置き換えるのが主な用途。
// 入力: { asset_no(現在の値。仮でも可), new_asset_no?, new_computer_name?, ip? }
//
// 更新の経路は強制しない。NetBox を直接編集してもよく、その場合は
// remind-scheduler の事後検証が state を追随させる。
// 設計: docs/design/02-pc-register.md#仮情報と正式化

const i = $input.first()?.json ?? {};
if (!i.asset_no) throw new Error('device-update: asset_no(現在の資産管理番号)は必須です');
if (!i.new_asset_no && !i.new_computer_name && !i.ip) {
  throw new Error('device-update: 更新する項目がありません(new_asset_no / new_computer_name / ip)');
}
for (const [k, v] of [['new_asset_no', i.new_asset_no]]) {
  if (v && !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(String(v))) {
    throw new Error(`device-update: ${k} に使えない文字が含まれます: ${v}`);
  }
}

return [{ json: {
  base: `${$env.NETBOX_URL}/api`,
  assetNo: String(i.asset_no),
  newAssetNo: i.new_asset_no ? String(i.new_asset_no) : null,
  newName: i.new_computer_name ? String(i.new_computer_name) : null,
  ip: i.ip || null,
}}];

// 更新後の値が他の機器と衝突しないか調べるための問い合わせを組み立てる。
// 常に1件は流して後段が止まらないようにする(自分自身を除外して判定する)。
const ctx = $('入力を検証する').first().json;
const res = $input.first()?.json ?? {};
const dev = res.results?.[0];
if (!dev) throw new Error(`device-update: 資産管理番号 ${ctx.assetNo} の機器が見つかりません`);

return [{ json: {
  ...ctx,
  deviceId: dev.id,
  currentName: dev.name,
  currentTags: (dev.tags ?? []).map((t) => t.slug),
  hasIp: Boolean(dev.primary_ip4),
  // 重複チェック用(変更しない項目は現在値を入れておき、自分自身は後で除外する)
  checkName: ctx.newName ?? dev.name,
  checkAsset: ctx.newAssetNo ?? ctx.assetNo,
}}];

// 自分自身は重複とみなさない。他の機器と衝突する場合だけ差し戻す。
const ctx = $('機器を特定する').first().json;
const byName = $('新しい名前の重複を確認').first().json;
const byAsset = $input.first().json;

const others = (res) => (res.results ?? []).filter((d) => d.id !== ctx.deviceId);
const dup = [];
if (ctx.newName && others(byName).length) dup.push(`コンピュータ名 '${ctx.checkName}'`);
if (ctx.newAssetNo && others(byAsset).length) dup.push(`資産管理番号 '${ctx.checkAsset}'`);
if (dup.length) {
  throw new Error(`device-update: 他の機器と重複しています(${dup.join(' / ')})`);
}

// 仮の値が両方とも解消されたら provisional タグを外す
const stillProvisional = !(ctx.newAssetNo && ctx.newName)
  && ctx.currentTags.includes('provisional')
  && !(ctx.newAssetNo && ctx.newName);

return [{ json: { ...ctx, kind: 'pcs', id: ctx.assetNo, stillProvisional } }];

// 台帳(state)を読み、値を更新した内容を作る。
// 資産管理番号が変わった場合は新しいファイル名で書き直す。
const ctx = $('重複を判定する').first().json;
return [{ json: { kind: 'pcs', id: ctx.assetNo } }];

// state の値を更新する。資産管理番号が変わるならファイル名も変わるため、
// 新しい id で全内容を書き直し(replace)、旧ファイルは後段で削除する。
const ctx = $('重複を判定する').first().json;
const rec = $input.first()?.json;
const state = rec?.state ?? {};

let ipResult = null;
try { ipResult = $('IPを割り当てる').first().json; } catch (e) { ipResult = null; }
const ipAssigned = ipResult?.ok === true;

const next = {
  ...state,
  computer_name: {
    value: ctx.newName ?? state.computer_name?.value ?? ctx.currentName,
    provisional: ctx.newName ? false : (state.computer_name?.provisional ?? false),
  },
  asset_no: {
    value: ctx.newAssetNo ?? ctx.assetNo,
    provisional: ctx.newAssetNo ? false : (state.asset_no?.provisional ?? false),
  },
  ...(ipAssigned ? { ip_address: ipResult.ip } : {}),
  updated_at: new Date().toISOString(),
};

const newId = ctx.newAssetNo ?? ctx.assetNo;
const renamed = newId !== ctx.assetNo;

return [{ json: {
  kind: 'pcs',
  id: newId,
  patch: next,
  replace: true,          // ファイル名が変わる場合があるので全置換
  reason: renamed ? `正式な資産管理番号へ変更(旧: ${ctx.assetNo})` : '機器情報を更新',
  __renamedFrom: renamed ? ctx.assetNo : null,
  __summary: {
    deviceId: ctx.deviceId,
    name: next.computer_name.value,
    assetNo: next.asset_no.value,
    ip: ipAssigned ? ipResult.ip : (state.ip_address ?? null),
    provisionalCleared: !ctx.stillProvisional,
  },
}}];

// タスクは閉じない。NetBox を直接編集した場合と扱いを揃えるため、
// 完了判定は remind-scheduler の事後検証に任せる(経路によって差が出ないように)。
const s = $('state を組み立てる').first().json.__summary;
const renamedFrom = $('state を組み立てる').first().json.__renamedFrom;
return [{ json: {
  ok: true,
  asset_no: s.assetNo,
  computer_name: s.name,
  ip: s.ip,
  provisional_cleared: s.provisionalCleared,
  renamed_from: renamedFrom,
  netbox_url: `${String($env.NETBOX_URL).replace('netbox:8080', 'localhost:8000')}/dcim/devices/${s.deviceId}/`,
}}];
